  const invalidOrders = [];
  const expeditedQueue = [];
  const normalQueue = [];

  for (const order of orders) {
    if (!order || typeof order !== 'object' || Array.isArray(order)) {
      invalidOrders.push({ id: null, reason: 'invalid_order' });
      continue;
